import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Datasets.md","filePath":"manual-zh/Datasets.md","lastUpdated":1785684581000}'),_={name:"manual-zh/Datasets.md"};function s(o,t,n,P,h,l){return d(),e("div",null,[...t[0]||(t[0]=[r('<h3 id="_6-7-数据集" tabindex="-1">6.7 数据集 <a class="header-anchor" href="#_6-7-数据集" aria-label="Permalink to &quot;6.7 数据集&quot;">​</a></h3><p>PSPP 处理组织为_数据集_的数据。一个数据集由一组_变量_组成，这些变量合在一起被称为构成一个_字典_，以及一个或多个_个案_，每个个案对每个变量各有一个值。</p><p>在任何时刻，PSPP 恰好有一个特殊的数据集，称为_活动数据集_。大多数 PSPP 命令只与活动数据集一起工作。除了活动数据集之外，PSPP 还支持任意数量的额外已打开数据集。<code>DATASET</code> 命令可以从已打开的数据集中选择一个新的活动数据集，以及创建和销毁数据集（参见 <a href="./DATASET">DATASET</a>）。</p><p>下面的各节更详细地描述变量。</p><table tabindex="0"><thead><tr><th>• 属性</th><th></th><th>变量的属性。</th></tr></thead><tbody><tr><td>• 系统变量</td><td></td><td>由 PSPP 自动定义的变量。</td></tr><tr><td>• 变量集合</td><td></td><td>变量名列表。</td></tr><tr><td>• 输入与输出格式</td><td></td><td>输入与输出格式。</td></tr><tr><td>• 暂用变量</td><td></td><td>由规程删除的变量。</td></tr></tbody></table>',5)])])}const i=a(_,[["render",s]]);export{c as __pageData,i as default};
